"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26160"],{48494(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.precondicao_requerida","status":428,"titulo":"A muta\xe7\xe3o exige o If-Match com o ETag corrente"},"descricao":{"codigo":"uniplus.selecao.precondicao_requerida","requisitos":["UNI-REQ-0021","UNI-REQ-0022"],"oQueAconteceu":["O pedido para alterar o rascunho do processo seletivo chegou **sem** o cabe\xe7alho\\n`If-Match`. A recusa sai com **428**, antes de qualquer regra de neg\xf3cio: a\\naltera\xe7\xe3o n\xe3o chegou a ser tentada.","O rascunho pode estar aberto por duas pessoas, ou em duas telas, ao mesmo\\ntempo. S\xf3 o `If-Match` com o `ETag` exato garante que o pedido parte da revis\xe3o\\nmais recente do rascunho, para que uma grava\xe7\xe3o n\xe3o apague outra sem que\\nningu\xe9m perceba.","A inscri\xe7\xe3o do candidato tem a pr\xf3pria precondi\xe7\xe3o, com outro c\xf3digo\\n(`uniplus.selecao.inscricao.precondicao_requerida`)."],"comoResolver":["Leia o rascunho (`GET /api/selecao/rascunhos-de-processos-seletivos/{id}`),\\nguarde o `ETag` da resposta e repita o pedido com `If-Match: <ETag>`. Cada\\naltera\xe7\xe3o aceita devolve um `ETag` novo: use-o no pedido seguinte."],"ondeAparece":["Substitui\xe7\xe3o do rascunho (`PUT /api/selecao/rascunhos-de-processos-seletivos/{id}`)","Exclus\xe3o do rascunho (`DELETE /api/selecao/rascunhos-de-processos-seletivos/{id}`)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Precondicao requerida"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);